args.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?song ?label ?released WHERE {
  VALUES ?song { <http://dbpedia.org/resource/Wherever_I_Lay_My_Hat_(That's_My_Home)> <http://dbpedia.org/resource/Don't_Ya> }
  ?song dbp:released ?released .
  OPTIONAL { ?song rdfs:label ?label . FILTER (lang(?label) = "en") }
}
ORDER BY ?released
LIMIT 1

